// @expect: 99.99 1e+2 99.99000000
// Number::toString uses shortest round-trip digits and the spec's exponent layout.
const values: number[] = [0, -0, 1, -1, 0.1, 0.1 + 0.2, Math.PI, 1 / 3, 123456789012345680000, 1e21, 1.5e-7, 0.000001, 1e-7, -2.5e-10, 5e-324, 1.7976931348623157e308, 9007199254740993, 100, 1234.5678, 2 ** 53, 0.5, 123e-20];
for (const value of values) {
  console.log(String(value), `${value}`, value.toString(), value);
}
console.log(values.join("|"));
console.log(JSON.stringify(values));
const typed = new Float64Array([0.1, 1e21, 1.5e-7]);
console.log(typed.toString());
const precisions: number[] = [1.5, 123.456, 0.000123, 1e21, 99.99];
for (const value of precisions) {
  console.log(value.toPrecision(4), value.toPrecision(1), value.toPrecision(10));
}
